import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
    .version 8.0
    .target sm_89
    .address_size 64
    .visible .entry the_entry_name(
      .param .u64 x_ptr,
      .param .u64 out_ptr,
      .param .u32 dim,
      .param .u32 N0,
      .param .u32 N1,
      .param .u32 N2
    )
    {
        .reg .pred %p0, %p1, %p2, %p_exit, %p_lt;
        .reg .u32 %r_tid, %r_ntid, %r_cta, %r_tmp, %r_total, %r_M1, %r_dim, %r_N0, %r_N1, %r_N2, %r_o0, %r_o1, %r_nred, %r_k, %r_grid, %r_step, %r_out, %r_n4, %r_tail, %r_i;
        .reg .u64 %rd_x, %rd_out, %rd_start, %rd_stride_bytes, %rd_valptr, %rd_offset_bytes, %rd_tmp64, %rd_N0, %rd_N1, %rd_N2, %rd_N1N2, %rd_align;
        .reg .f32 %f_min, %f_val, %f_v0, %f_v1, %f_v2, %f_v3;
        // Load kernel parameters
        ld.param.u64 %rd_x, [x_ptr];
        ld.param.u64 %rd_out, [out_ptr];
        ld.param.u32 %r_dim, [dim];
        ld.param.u32 %r_N0, [N0];
        ld.param.u32 %r_N1, [N1];
        ld.param.u32 %r_N2, [N2];
        // Compute linear thread id
        mov.u32 %r_tid, %tid.x;
        mov.u32 %r_ntid, %ntid.x;
        mov.u32 %r_cta, %ctaid.x;
        mad.lo.u32 %r_tid, %r_cta, %r_ntid, %r_tid;
        // Precompute 64-bit products
        cvt.u64.u32 %rd_N1, %r_N1;
        cvt.u64.u32 %rd_N2, %r_N2;
        mul.lo.u64 %rd_N1N2, %rd_N1, %rd_N2;
        // Determine output size and row-major M1 (last-dimension size)
        setp.eq.u32 %p0, %r_dim, 0;
        @%p0 bra DIM0;
        setp.eq.u32 %p1, %r_dim, 1;
        @%p1 bra DIM1;
        // else dim == 2
        mov.u32 %r_M1, %r_N1;              // M1 = N1
        mul.lo.u32 %r_total, %r_N0, %r_N1; // total = N0*N1
        bra AFTER_SZ;
    DIM0:
        mov.u32 %r_M1, %r_N2;              // M1 = N2
        mul.lo.u32 %r_total, %r_N1, %r_N2; // total = N1*N2
        bra AFTER_SZ;
    DIM1:
        mov.u32 %r_M1, %r_N2;              // M1 = N2
        mul.lo.u32 %r_total, %r_N0, %r_N2; // total = N0*N2
    AFTER_SZ:
        // Compute grid-stride parameters
        mov.u32 %r_grid, %nctaid.x;
        mul.lo.u32 %r_step, %r_grid, %r_ntid;
        // Initialize outer index with linear thread id
        mov.u32 %r_out, %r_tid;
    OUTER_LOOP:
        // Bounds check for current output index
        setp.ge.u32 %p_exit, %r_out, %r_total;
        @%p_exit bra END;
        // Map out -> (o0, o1) with row-major layout (M1 is last-dimension size)
        div.u32 %r_o0, %r_out, %r_M1;
        mul.lo.u32 %r_tmp, %r_o0, %r_M1;
        sub.u32 %r_o1, %r_out, %r_tmp;
        // Compute start index, stride (in elements), and nred for each dim case
        setp.eq.u32 %p0, %r_dim, 0;
        @%p0 bra SET_DIM0;
        setp.eq.u32 %p1, %r_dim, 1;
        @%p1 bra SET_DIM1;
        // SET_DIM2:
        // start = o0*(N1*N2) + o1*N2; nred = N2; stride = 1
        cvt.u64.u32 %rd_tmp64, %r_o0;
        mul.lo.u64 %rd_start, %rd_tmp64, %rd_N1N2;
        cvt.u64.u32 %rd_tmp64, %r_o1;
        mul.lo.u64 %rd_tmp64, %rd_tmp64, %rd_N2;
        add.u64 %rd_start, %rd_start, %rd_tmp64;
        mov.u32 %r_nred, %r_N2;
        mov.u64 %rd_stride_bytes, 4; // stride=1 element -> 4 bytes
        bra READY;
    SET_DIM0:
        // start = o0*N2 + o1; nred = N0; stride = N1*N2
        cvt.u64.u32 %rd_tmp64, %r_o0;
        mul.lo.u64 %rd_start, %rd_tmp64, %rd_N2;
        cvt.u64.u32 %rd_tmp64, %r_o1;
        add.u64 %rd_start, %rd_start, %rd_tmp64;
        mov.u32 %r_nred, %r_N0;
        // stride_bytes = (N1*N2)*4
        shl.b64 %rd_stride_bytes, %rd_N1N2, 2;
        bra READY;
    SET_DIM1:
        // start = o0*(N1*N2) + o1; nred = N1; stride = N2
        cvt.u64.u32 %rd_tmp64, %r_o0;
        mul.lo.u64 %rd_start, %rd_tmp64, %rd_N1N2;
        cvt.u64.u32 %rd_tmp64, %r_o1;
        add.u64 %rd_start, %rd_start, %rd_tmp64;
        mov.u32 %r_nred, %r_N1;
        // stride_bytes = N2*4
        cvt.u64.u32 %rd_stride_bytes, %r_N2;
        shl.b64 %rd_stride_bytes, %rd_stride_bytes, 2;
    READY:
        // Value pointer = x_ptr + (start * 4)
        shl.b64 %rd_offset_bytes, %rd_start, 2;
        add.u64 %rd_valptr, %rd_x, %rd_offset_bytes;
        // Initialize min accumulator to +inf
        mov.b32 %f_min, 0x7f800000;
        // Choose reduction path: vectorized when contiguous along dim2 (stride_bytes == 4)
        mov.u64 %rd_tmp64, 4;
        setp.eq.u64 %p2, %rd_stride_bytes, %rd_tmp64;
        @%p2 bra CONTIG_VEC;
    SCALAR_PATH:
        // Unrolled reduction by factor 4 (generic stride)
        // Compute number of 4-element groups and tail
        shr.u32 %r_n4, %r_nred, 2;
        mov.u32 %r_i, 0;
    LOOP4:
        setp.ge.u32 %p2, %r_i, %r_n4;
        @%p2 bra LOOP4_END;
        ld.global.cs.f32 %f_val, [%rd_valptr];
        setp.lt.f32 %p_lt, %f_val, %f_min;
        @%p_lt mov.f32 %f_min, %f_val;
        add.u64 %rd_valptr, %rd_valptr, %rd_stride_bytes;
        ld.global.cs.f32 %f_val, [%rd_valptr];
        setp.lt.f32 %p_lt, %f_val, %f_min;
        @%p_lt mov.f32 %f_min, %f_val;
        add.u64 %rd_valptr, %rd_valptr, %rd_stride_bytes;
        ld.global.cs.f32 %f_val, [%rd_valptr];
        setp.lt.f32 %p_lt, %f_val, %f_min;
        @%p_lt mov.f32 %f_min, %f_val;
        add.u64 %rd_valptr, %rd_valptr, %rd_stride_bytes;
        ld.global.cs.f32 %f_val, [%rd_valptr];
        setp.lt.f32 %p_lt, %f_val, %f_min;
        @%p_lt mov.f32 %f_min, %f_val;
        add.u64 %rd_valptr, %rd_valptr, %rd_stride_bytes;
        add.u32 %r_i, %r_i, 1;
        bra LOOP4;
    LOOP4_END:
        and.b32 %r_tail, %r_nred, 3;
        mov.u32 %r_k, 0;
    TAIL_LOOP:
        setp.ge.u32 %p2, %r_k, %r_tail;
        @%p2 bra REDUCE_DONE;
        ld.global.cs.f32 %f_val, [%rd_valptr];
        setp.lt.f32 %p_lt, %f_val, %f_min;
        @%p_lt mov.f32 %f_min, %f_val;
        add.u64 %rd_valptr, %rd_valptr, %rd_stride_bytes;
        add.u32 %r_k, %r_k, 1;
        bra TAIL_LOOP;
    CONTIG_VEC:
        // Vectorized reduction for contiguous case (dim == 2), handle alignment prologue
        and.b64 %rd_align, %rd_valptr, 15;
        setp.eq.u64 %p0, %rd_align, 0;
        @%p0 bra VEC_MAIN;
        // s = min(((16 - align) >> 2), nred)
        neg.s64 %rd_tmp64, %rd_align;
        add.s64 %rd_tmp64, %rd_tmp64, 16;
        shr.u64 %rd_tmp64, %rd_tmp64, 2;
        cvt.u32.u64 %r_tmp, %rd_tmp64;
        setp.gt.u32 %p1, %r_tmp, %r_nred;
        @!%p1 bra S_CLAMPED;
        mov.u32 %r_tmp, %r_nred;
    S_CLAMPED:
        mov.u32 %r_k, 0;
    ALIGN_SCALAR:
        setp.ge.u32 %p2, %r_k, %r_tmp;
        @%p2 bra ALIGN_DONE;
        ld.global.cs.f32 %f_val, [%rd_valptr];
        setp.lt.f32 %p_lt, %f_val, %f_min;
        @%p_lt mov.f32 %f_min, %f_val;
        add.u64 %rd_valptr, %rd_valptr, 4;
        add.u32 %r_k, %r_k, 1;
        bra ALIGN_SCALAR;
    ALIGN_DONE:
        sub.u32 %r_nred, %r_nred, %r_tmp;
    VEC_MAIN:
        // Process 4-wide groups with ld.global.v4.f32
        shr.u32 %r_n4, %r_nred, 2;
        mov.u32 %r_i, 0;
    VEC_LOOP4:
        setp.ge.u32 %p2, %r_i, %r_n4;
        @%p2 bra VEC_LOOP4_END;
        ld.global.cs.v4.f32 {%f_v0, %f_v1, %f_v2, %f_v3}, [%rd_valptr];
        setp.lt.f32 %p_lt, %f_v0, %f_min;
        @%p_lt mov.f32 %f_min, %f_v0;
        setp.lt.f32 %p_lt, %f_v1, %f_min;
        @%p_lt mov.f32 %f_min, %f_v1;
        setp.lt.f32 %p_lt, %f_v2, %f_min;
        @%p_lt mov.f32 %f_min, %f_v2;
        setp.lt.f32 %p_lt, %f_v3, %f_min;
        @%p_lt mov.f32 %f_min, %f_v3;
        add.u64 %rd_valptr, %rd_valptr, 16;
        add.u32 %r_i, %r_i, 1;
        bra VEC_LOOP4;
    VEC_LOOP4_END:
        and.b32 %r_tail, %r_nred, 3;
        mov.u32 %r_k, 0;
    VEC_TAIL:
        setp.ge.u32 %p2, %r_k, %r_tail;
        @%p2 bra REDUCE_DONE;
        ld.global.cs.f32 %f_val, [%rd_valptr];
        setp.lt.f32 %p_lt, %f_val, %f_min;
        @%p_lt mov.f32 %f_min, %f_val;
        add.u64 %rd_valptr, %rd_valptr, 4;
        add.u32 %r_k, %r_k, 1;
        bra VEC_TAIL;
    REDUCE_DONE:
        // Store result: out[out_idx] = min
        cvt.u64.u32 %rd_tmp64, %r_out;
        shl.b64 %rd_tmp64, %rd_tmp64, 2;
        add.u64 %rd_tmp64, %rd_out, %rd_tmp64;
        st.global.f32 [%rd_tmp64], %f_min;
        // Advance to next output index handled by this thread
        add.u32 %r_out, %r_out, %r_step;
        bra OUTER_LOOP;
    END:
        ret;
    }
