_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("the_entry_name")

class ModelNew(nn.Module):
    def __init__(self, dim: int):
        super().__init__()
        self.dim = int(dim)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input tensor must be on CUDA device"
        assert x.dim() == 3, "Input tensor must be 3D"
        assert x.dtype == torch.float32, "Only float32 tensors are supported"
        B, D1, D2 = x.shape
        dim = self.dim
        if dim < 0:
            dim = dim + 3
        assert 0 <= dim < 3, "Reduction dim out of range for 3D tensor"
        if dim == 0:
            out_shape = (D1, D2)
            total_out = D1 * D2
        elif dim == 1:
            out_shape = (B, D2)
            total_out = B * D2
        else:
            out_shape = (B, D1)
            total_out = B * D1

        out = torch.empty(out_shape, dtype=x.dtype, device=x.device)

        block_x = 256
        grid_x = (total_out + block_x - 1) // block_x

        module = _get_ptx_module()
        module.launch(
            "the_entry_name",
            grid=(int(grid_x), 1, 1),
            block=(block_x, 1, 1),
            arguments=[x, out, i32(dim), i32(B), i32(D1), i32(D2)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

