        module.launch(
            "the_entry_name",
            grid=(int(grid_x), 1, 1),
            block=(block_x, 1, 1),
            arguments=[x, out, i32(dim), i32(B), i32(D1), i32(D2)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out
